INSERT INTO host_vuln_task (
    tenant_id, task_name, task_type, host_id, mac_address, scan_mode, rule_count,
    status, triggered_by, started_at, summary_json, created_at
) VALUES (
    COALESCE(#{tenantId}, 0), #{taskName}, #{taskType}, #{hostId}, #{macAddress}, #{scanMode}, #{ruleCount},
    #{status}, #{triggeredBy}, #{startedAt}, #{summaryJson}, #{createdAt}
)

mapper.select:
SELECT id, tenant_id, task_name, task_type, host_id, mac_address, scan_mode, rule_count,
       status, triggered_by, started_at, finished_at, summary_json, created_at
FROM host_vuln_task
WHERE id = #{id}
  AND tenant_id = #{tenantId}

